"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["46716"],{82293(e){e.exports=JSON.parse('{"id":"V4-221","slug":"super-app","term":"Super App","also_known_as":[],"difficulty":"Intermediate","definition":"A super app is a mobile application that combines many different services, such as messaging, payments, shopping, transport, food delivery and financial services, within a single platform.","explanation":["Instead of downloading separate apps for each service, users of a super app can do many everyday tasks in one place. Financial services, especially payments, are usually at the heart of super apps, linking the different services together.","The best-known examples come from Asia. China\u2019s WeChat, run by Tencent, began as a messaging app and expanded into payments, shopping, bill payment, government services and mini-programs from other businesses. Alipay, run by Ant Group, combines payments with savings, investments, insurance and lending. In Southeast Asia, Grab offers ride-hailing, food delivery, payments and financial services. India\u2019s Paytm developed in a similar direction.","For example, a user of a super app might chat with friends, order dinner, book a taxi, pay utility bills and invest savings without leaving the app.","Super apps benefit from network effects and large amounts of customer data, which they can use to offer personalised services and credit. However, they raise concerns about competition, data privacy and concentration of financial risk. Several Western technology companies have expressed ambitions to build super apps, but none has matched the scale of the Asian examples."],"note":"","total":1725,"prev":{"slug":"sunk-cost","term":"Sunk Cost"},"next":{"slug":"superannuation","term":"Superannuation"}}')}}]);